using Clock=std::chrono::steady_clock;
static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Buffer{char* p=nullptr;size_t size=0;char* get(size_t n){if(n>size){size_t free,total;ck(cudaMemGetInfo(&free,&total));size_t reserve=std::max<size_t>(2ull<<30,total*0.15);if(n>free||free-n<reserve)throw std::runtime_error("VRAM headroom guard");if(p)ck(cudaFree(p));ck(cudaMalloc(&p,n));size=n;}return p;}~Buffer(){if(p)cudaFree(p);}};
struct Data {int n;std::vector<float> xyz,sh,opacity,scale,rotation;};
Data load_model(const std::string& name){std::ifstream f(name,std::ios::binary);if(!f)throw std::runtime_error("model open");std::string line;std::getline(f,line);if(line!="ply")throw std::runtime_error("not PLY");int n=0;std::vector<std::string> fields;bool binary=false,vertex=false;while(std::getline(f,line)&&line!="end_header"){std::istringstream in(line);std::string k,a,b;in>>k>>a>>b;if(k=="format")binary=a=="binary_little_endian";if(k=="element"){vertex=a=="vertex";if(vertex)n=std::stoi(b);}if(k=="property"){if(!vertex||a!="float")throw std::runtime_error("unsupported PLY property");fields.push_back(b);}}if(!binary||n<1||n>10000000||fields.size()!=62)throw std::runtime_error("unsupported Gaussian PLY schema");std::map<std::string,int> ix;for(int j=0;j<(int)fields.size();j++)ix[fields[j]]=j;auto at=[&](const std::string&s){return ix.at(s);};std::vector<float> rows(size_t(n)*fields.size());f.read((char*)rows.data(),rows.size()*4);if(!f)throw std::runtime_error("truncated PLY");Data d;d.n=n;d.xyz.resize(n*3ull);d.sh.resize(n*48ull);d.opacity.resize(n);d.scale.resize(n*3ull);d.rotation.resize(n*4ull);for(int i=0;i<n;i++){auto r=rows.data()+size_t(i)*fields.size();for(int k=0;k<62;k++)if(!std::isfinite(r[k]))throw std::runtime_error("nonfinite model");for(int j=0;j<3;j++){d.xyz[i*3+j]=r[at(j==0?"x":j==1?"y":"z")];d.scale[i*3+j]=std::exp(r[at("scale_"+std::to_string(j))]);d.sh[i*48+j]=r[at("f_dc_"+std::to_string(j))];for(int k=1;k<16;k++)d.sh[i*48+k*3+j]=r[at("f_rest_"+std::to_string(j*15+k-1))];}d.opacity[i]=1.f/(1.f+std::exp(-r[at("opacity")]));float norm=0;for(int j=0;j<4;j++){float a=r[at("rot_"+std::to_string(j))];norm+=a*a;}norm=std::sqrt(norm);if(!(norm>0))throw std::runtime_error("bad quaternion");for(int j=0;j<4;j++)d.rotation[i*4+j]=r[at("rot_"+std::to_string(j))]/norm;}
return d;}
struct Camera{float view[16],proj[16],pos[3],tanx,tany;};
std::vector<Camera> load_cameras(const std::string& name){std::ifstream f(name,std::ios::binary);uint32_t n;f.read((char*)&n,4);if(!f||n<3||n>10000)throw std::runtime_error("bad cameras");std::vector<Camera> c(n);static_assert(sizeof(Camera)==37*4);f.read((char*)c.data(),n*sizeof(Camera));if(!f)throw std::runtime_error("truncated cameras");return c;}
static uint64_t hash64(const void* p,size_t bytes){auto b=(const unsigned char*)p;uint64_t h=1469598103934665603ull;for(size_t i=0;i<bytes;i++)h=(h^b[i])*1099511628211ull;return h;}
static float* upload(Buffer& b,const std::vector<float>& x){float* p=(float*)b.get(x.size()*4);ck(cudaMemcpy(p,x.data(),x.size()*4,cudaMemcpyHostToDevice));return p;}
struct Digest{unsigned long long x,s;unsigned int bad,mismatch;};
__device__ unsigned long long mix64(unsigned long long x){x^=x>>30;x*=0xbf58476d1ce4e5b9ull;x^=x>>27;x*=0x94d049bb133111ebull;return x^(x>>31);}
__global__ void digest(const uint32_t* color,const uint32_t* alpha,const uint32_t* contrib,const uint32_t* reference,size_t pixels,Digest* d){unsigned long long x=0,s=0;unsigned int bad=0,diff=0;for(size_t i=blockIdx.x*blockDim.x+threadIdx.x;i<5*pixels;i+=gridDim.x*blockDim.x){uint32_t w=i<3*pixels?color[i]:i<4*pixels?alpha[i-3*pixels]:contrib[i-4*pixels];auto h=mix64((static_cast<unsigned long long>(i)<<32)^w);x^=h;s+=h;if(i<4*pixels&&(w&0x7f800000u)==0x7f800000u)bad++;if(reference)diff+=w!=reference[i];}atomicXor(&d->x,x);atomicAdd(&d->s,s);atomicAdd(&d->bad,bad);atomicAdd(&d->mismatch,diff);}
struct Setting{int id,q,k;double alpha;};
std::vector<Setting> settings(std::string input){std::vector<Setting> out;std::stringstream lines(input);std::string s;while(std::getline(lines,s,',')){std::replace(s.begin(),s.end(),':',' ');std::istringstream in(s);Setting v;if(!(in>>v.id>>v.q>>v.k>>v.alpha)||v.id<0||v.id>8||(v.q!=8&&v.q!=16)||(v.k!=4&&v.k!=8)||v.alpha<=0||v.alpha>1)throw std::runtime_error("bad settings");out.push_back(v);}return out;}
int camera_index(int n,const std::string& track,int frame){int a=n/5,b=3*n/5;if(track=="calib")return frame%a;if(track=="slow")return a+(frame/4)%(b-a);if(track=="fast")return b+(frame*2)%(n-b);throw std::runtime_error("bad trajectory");}
int main(int argc,char**argv){try{
 if(argc!=12)throw std::runtime_error("Usage: benchmark scene W H track settings frames warm_frames warm_seconds out mode executor");std::string dir=argv[1],track=argv[4],outdir=argv[9],mode=argv[10];int W=std::stoi(argv[2]),H=std::stoi(argv[3]),frames=std::stoi(argv[6]),warm=std::stoi(argv[7]),executor=std::stoi(argv[11]);double warmsec=std::stod(argv[8]);auto ss=settings(argv[5]);if(W<1||H<1||W>2560||H>1440||frames<1||frames>4096||warm<0||warm>8192||warmsec<0||warmsec>30)throw std::runtime_error("invalid bounds");std::filesystem::create_directories(outdir);Data d=load_model(dir+"/point_cloud/iteration_30000/point_cloud.ply");auto cams=load_cameras(dir+"/camera_replay.bin");Buffer bx,bs,bo,bc,br,bg,bcam,bout,geom,bin,img,bhash,bref;float* xyz=upload(bx,d.xyz),*sh=upload(bs,d.sh),*opacity=upload(bo,d.opacity),*scale=upload(bc,d.scale),*rot=upload(br,d.rotation);std::vector<float> bgv(3,0);float* background=upload(bg,bgv);size_t pixels=size_t(W)*H;float* output=(float*)bout.get(pixels*12);float* cam=(float*)bcam.get(sizeof(Camera));auto hd=(Digest*)bhash.get(sizeof(Digest));auto reference=(uint32_t*)bref.get(pixels*20);cudaEvent_t begin,end;ck(cudaEventCreate(&begin));ck(cudaEventCreate(&end));schedule_config.executor=executor;schedule_init();
 std::ofstream csv(outdir+"/frames.csv"),qual(outdir+"/quality.csv"),sessions(outdir+"/sessions.csv");csv<<"policy,q,k,alpha,frame,camera,gpu_span_ms,cpu_result_ready_ms,instances,preprocess_ms,scan_ms,sort_ms,build_ms,render_ms,cpu_plan_ms,bundles,cap_hits,hash_x,hash_sum,finite\n";qual<<"frame,camera,policy,q,k,alpha,raw_mismatches,nonfinite,hash_x,hash_sum,raw_file\n";sessions<<"policy,q,k,alpha,warmup_frames,warmup_seconds,measured_frames,workers,executor\n";
 auto apply=[&](Setting s){schedule_config.policy=s.id;schedule_config.q=s.q;schedule_config.k=s.k;schedule_config.alpha=s.alpha;};
 int instances=0;float gpu_ms=0;double cpu_ms=0;auto frame_run=[&](int ci){auto a=Clock::now();ck(cudaEventRecord(begin));ck(cudaMemcpy(cam,&cams[ci],sizeof(Camera),cudaMemcpyHostToDevice));instances=CudaRasterizer::Rasterizer::forward([&](size_t n){return geom.get(n);},[&](size_t n){return bin.get(n);},[&](size_t n){return img.get(n);},d.n,3,16,background,W,H,xyz,sh,nullptr,opacity,scale,1.f,rot,nullptr,cam,cam+16,cam+32,cams[ci].tanx,cams[ci].tany,false,output,nullptr,false);ck(cudaGetLastError());ck(cudaEventRecord(end));ck(cudaEventSynchronize(end));cpu_ms=std::chrono::duration<double,std::milli>(Clock::now()-a).count();ck(cudaEventElapsedTime(&gpu_ms,begin,end));schedule_times();if(schedule_stats.render_ms>20||schedule_stats.preprocess_ms>20)throw std::runtime_error("measured render/preprocess kernel >20ms; stop this configuration");};
 auto state=[&](){char* ptr=img.p;return CudaRasterizer::ImageState::fromChunk(ptr,pixels);};
 auto hash=[&](bool compare){auto st=state();ck(cudaMemset(hd,0,sizeof(Digest)));digest<<<256,256>>>((uint32_t*)output,(uint32_t*)st.accum_alpha,st.n_contrib,compare?reference:nullptr,pixels,hd);Digest x;ck(cudaMemcpy(&x,hd,sizeof(x),cudaMemcpyDeviceToHost));if(x.bad)throw std::runtime_error("nonfinite output");return x;};
 auto keep_reference=[&](){auto st=state();ck(cudaMemcpy(reference,output,pixels*12,cudaMemcpyDeviceToDevice));ck(cudaMemcpy(reference+pixels*3,st.accum_alpha,pixels*4,cudaMemcpyDeviceToDevice));ck(cudaMemcpy(reference+pixels*4,st.n_contrib,pixels*4,cudaMemcpyDeviceToDevice));};
 auto save=[&](const Digest& h){auto st=state();std::vector<uint32_t> data(pixels*5);ck(cudaMemcpy(data.data(),output,pixels*12,cudaMemcpyDeviceToHost));ck(cudaMemcpy(data.data()+pixels*3,st.accum_alpha,pixels*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(data.data()+pixels*4,st.n_contrib,pixels*4,cudaMemcpyDeviceToHost));std::filesystem::path base=std::filesystem::path(outdir).parent_path()/"raw_cas";std::filesystem::create_directories(base);std::string name=std::to_string(W)+"x"+std::to_string(H)+"_"+std::to_string(h.x)+"_"+std::to_string(h.s)+".bin";auto path=base/name;if(std::filesystem::exists(path)){std::ifstream f(path,std::ios::binary);std::vector<uint32_t> old(data.size());f.read((char*)old.data(),old.size()*4);if(!f||old!=data)throw std::runtime_error("raw identity collision");}else{std::ofstream f(path,std::ios::binary);f.write((char*)data.data(),data.size()*4);if(!f)throw std::runtime_error("raw write failed");}return path.string();};
 if(mode=="qual"){
  auto warm_settings=ss;warm_settings.insert(warm_settings.begin(),{0,8,4,.5});
  for(auto s:warm_settings){apply(s);int nf=0;auto ws=Clock::now();do{frame_run(camera_index(cams.size(),track,nf++));}while(nf<warm||std::chrono::duration<double>(Clock::now()-ws).count()<warmsec);sessions<<s.id<<','<<s.q<<','<<s.k<<','<<s.alpha<<','<<nf<<','<<std::chrono::duration<double>(Clock::now()-ws).count()<<",0,"<<schedule_config.workers<<','<<executor<<'\n';}
  for(int i=0;i<frames;i++){int fi=int(std::lround(i*511.0/(frames-1)));int ci=camera_index(cams.size(),track,fi);apply({0,8,4,.5});frame_run(ci);auto ref=hash(false);keep_reference();auto file=save(ref);qual<<fi<<','<<ci<<",0,8,4,0.5,0,"<<ref.bad<<','<<ref.x<<','<<ref.s<<','<<file<<'\n';for(int repeat=0;repeat<2;repeat++){frame_run(ci);auto h=hash(true);if(h.mismatch)throw std::runtime_error("native is not bitwise repeatable");}for(auto s:ss){apply(s);frame_run(ci);auto h=hash(true);qual<<fi<<','<<ci<<','<<s.id<<','<<s.q<<','<<s.k<<','<<s.alpha<<','<<h.mismatch<<','<<h.bad<<','<<h.x<<','<<h.s<<','<<file<<'\n';if(h.mismatch)throw std::runtime_error("full-output bitwise mismatch");}}
 }else{
  for(auto s:ss){apply(s);int nf=0;auto ws=Clock::now();do{frame_run(camera_index(cams.size(),track,nf));nf++;}while(nf<warm||std::chrono::duration<double>(Clock::now()-ws).count()<warmsec);double wall=std::chrono::duration<double>(Clock::now()-ws).count();sessions<<s.id<<','<<s.q<<','<<s.k<<','<<s.alpha<<','<<nf<<','<<wall<<','<<frames<<','<<schedule_config.workers<<','<<executor<<'\n';
   for(int frame=0;frame<frames;frame++){int ci=camera_index(cams.size(),track,frame);frame_run(ci);Digest h{};if(mode!="nodig"||frame==frames-1)h=hash(false);std::string file;if(mode=="formal"&&(frame==0||frame==frames/2||frame==frames-1))file=save(h);csv<<s.id<<','<<s.q<<','<<s.k<<','<<s.alpha<<','<<frame<<','<<ci<<','<<std::setprecision(9)<<gpu_ms<<','<<cpu_ms<<','<<instances<<','<<schedule_stats.preprocess_ms<<','<<schedule_stats.scan_ms<<','<<schedule_stats.sort_ms<<','<<schedule_stats.build_ms<<','<<schedule_stats.render_ms<<','<<schedule_stats.cpu_plan_ms<<','<<schedule_stats.bundles<<','<<schedule_stats.cap_hits<<','<<h.x<<','<<h.s<<','<<((mode!="nodig"||frame==frames-1)?1:-1)<<'\n';if(!file.empty())qual<<frame<<','<<ci<<','<<s.id<<','<<s.q<<','<<s.k<<','<<s.alpha<<",0,0,"<<h.x<<','<<h.s<<','<<file<<'\n';}
  }
 }
 std::cout<<"{\"mode\":\""<<mode<<"\",\"policies\":"<<ss.size()<<",\"frames\":"<<frames<<",\"gaussians\":"<<d.n<<",\"width\":"<<W<<",\"height\":"<<H<<",\"workers\":"<<schedule_config.workers<<",\"allocated_model_and_scratch_bytes\":"<<bx.size+bs.size+bo.size+bc.size+br.size+bg.size+bcam.size+bout.size+geom.size+bin.size+img.size+bhash.size+bref.size<<"}\n";return 0;
 }catch(std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
